const fs = require('fs');
const os = require('os');
const path = require('path');
const { startDevServer } = require('/tmp/story_97751a9bf9bc/dist/server.js');

async function getFreePort() {
  return new Promise((resolve, reject) => {
    const s = http.createServer();
    s.listen(0, '127.0.0.1', () => { const p = s.address().port; s.close(() => resolve(p)); });
    s.once('error', reject);
  });
}
async function request(url) {
  return new Promise((resolve) => http.get(url, { agent: false }, (res) => { res.resume(); res.on('end', resolve); }));
}

