  for (let i = 0; i < 3; i++) {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 's2-'));
    fs.mkdirSync(path.join(root, 'content'), { recursive: true });
    fs.writeFileSync(path.join(root, 'content', 'a.md'), 'x');
    const server = await startDevServer({ contentDir: path.join(root,'content'), outputDir: path.join(root,'dist'), templatesDir: path.join(root,'templates'), port: await getFreePort(), host: '127.0.0.1' });
    await request(`http://127.0.0.1:${server.port}/`);
    await server.close();
    fs.rmSync(root, { recursive: true, force: true });
  }
  const h = process._getActiveHandles();
  console.log('final handles:', h.map(x => `${x.constructor.name}(local=${x.localPort} remote=${x.remotePort} destroyed=${x.destroyed})`));
})();
EOF
